package ai.finsight.intelligence;

import ai.finsight.budget.*;import ai.finsight.recurring.*;import ai.finsight.transaction.*;import ai.finsight.user.UserRepository;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.math.*;import java.time.*;import java.util.*;

@Service public class SpendingIntelligenceService{
 public record CategorySpend(String category,BigDecimal amount){}public record MonthlyTrend(String month,BigDecimal income,BigDecimal expenses,BigDecimal savings,boolean partialMonth){}public record Observation(String category,BigDecimal currentMonthSpend,BigDecimal previousThreeMonthAverage,BigDecimal increase,boolean elevated,String interpretation){}public record BudgetOverrun(String name,String category,BigDecimal limit,BigDecimal spent,BigDecimal remaining,String status){}public record RecurringConcentration(String category,BigDecimal monthlyEquivalent){}public record Report(List<CategorySpend> topCategories,List<MonthlyTrend> monthlyTrends,List<Observation> categoryObservations,List<BudgetOverrun> budgetOverruns,List<RecurringConcentration> recurringPaymentConcentration,List<String> notes){}
 private final UserRepository users;private final TransactionRepository tx;private final BudgetService budgets;private final RecurringTransactionRepository recurring;
 public SpendingIntelligenceService(UserRepository u,TransactionRepository t,BudgetService b,RecurringTransactionRepository r){users=u;tx=t;budgets=b;recurring=r;}
 @Transactional(readOnly=true) public Report report(String email){UUID owner=users.findByEmailIgnoreCase(email).orElseThrow().getId();YearMonth current=YearMonth.now();List<CategorySpend> top=tx.categoryTotals(owner,current.atDay(1),current.plusMonths(1).atDay(1),FinancialTransaction.Direction.EXPENSE).stream().map(row->new CategorySpend((String)row[0],money((BigDecimal)row[1]))).toList();List<MonthlyTrend> trends=new ArrayList<>();for(int i=5;i>=0;i--){YearMonth month=current.minusMonths(i);BigDecimal income=money(tx.sumForOwnerAndPeriod(owner,month.atDay(1),month.plusMonths(1).atDay(1),FinancialTransaction.Direction.INCOME));BigDecimal expenses=money(tx.sumForOwnerAndPeriod(owner,month.atDay(1),month.plusMonths(1).atDay(1),FinancialTransaction.Direction.EXPENSE));trends.add(new MonthlyTrend(month.toString(),income,expenses,money(income.subtract(expenses)),i==0));}
  Map<String,BigDecimal> currentByCategory=new LinkedHashMap<>();top.forEach(c->currentByCategory.put(c.category(),c.amount()));Set<String> categories=new TreeSet<>(currentByCategory.keySet());for(Object[] row:tx.categoryTotals(owner,current.minusMonths(3).atDay(1),current.atDay(1),FinancialTransaction.Direction.EXPENSE))categories.add((String)row[0]);List<Observation> observations=new ArrayList<>();for(String category:categories){BigDecimal currentSpend=currentByCategory.getOrDefault(category,BigDecimal.ZERO.setScale(2));BigDecimal historic=BigDecimal.ZERO;for(int i=3;i>=1;i--){YearMonth month=current.minusMonths(i);historic=historic.add(tx.sumForOwnerCategoryPeriod(owner,month.atDay(1),month.plusMonths(1).atDay(1),FinancialTransaction.Direction.EXPENSE,category));}BigDecimal average=money(historic.divide(BigDecimal.valueOf(3),2,RoundingMode.HALF_UP));BigDecimal increase=money(currentSpend.subtract(average));boolean elevated=increase.compareTo(new BigDecimal("1000.00"))>=0&&currentSpend.compareTo(average.multiply(new BigDecimal("1.50")))>0;observations.add(new Observation(category,currentSpend,average,increase,elevated,elevated?"Higher than this user's own three-complete-month baseline; an observation, not a fraud finding.":"No material increase detected against this user's own baseline."));}observations.sort(Comparator.comparing(Observation::increase).reversed());List<BudgetOverrun> overruns=budgets.list(email).stream().filter(b->b.status().equals("EXCEEDED")||b.status().equals("ALERT")).map(b->new BudgetOverrun(b.name(),b.category(),b.monthlyLimit(),b.amountSpent(),b.remainingAmount(),b.status())).toList();Map<String,BigDecimal> recurrenceByCategory=new TreeMap<>();for(RecurringTransaction r:recurring.findAllByUserIdOrderByNextDueDateAsc(owner)){if(r.isActive()&&(r.getEndDate()==null||!r.getEndDate().isBefore(LocalDate.now()))&&r.getType()==RecurringTransaction.Type.EXPENSE)recurrenceByCategory.merge(r.getCategory(),monthlyized(r.getAmount(),r.getFrequency()),BigDecimal::add);}List<RecurringConcentration> concentration=recurrenceByCategory.entrySet().stream().map(e->new RecurringConcentration(e.getKey(),money(e.getValue()))).sorted(Comparator.comparing(RecurringConcentration::monthlyEquivalent).reversed()).toList();return new Report(top,List.copyOf(trends),List.copyOf(observations),overruns,concentration,List.of("Category totals include actual EXPENSE transactions only; income is excluded.","Monthly trend includes the current partial month and is not directly comparable to full months.","Elevated category observations require at least ₹1,000 increase and more than 50% above the user's three-complete-month average; this is not fraud detection.","Savings is actual income minus actual expenses for each month."));}
 private BigDecimal monthlyized(BigDecimal a,RecurringTransaction.Frequency f){return switch(f){case DAILY->a.multiply(BigDecimal.valueOf(30));case WEEKLY->a.multiply(BigDecimal.valueOf(52)).divide(BigDecimal.valueOf(12),2,RoundingMode.HALF_UP);case MONTHLY->a;case YEARLY->a.divide(BigDecimal.valueOf(12),2,RoundingMode.HALF_UP);};}private BigDecimal money(BigDecimal v){return v.setScale(2,RoundingMode.HALF_UP);}
}
